  const body = `
    <h1>Dashboard</h1>
    <p><strong>Email:</strong> ${email}</p>
    <div class="meta">
      <p><strong>iat:</strong> ${issuedAt}</p>
      <p><strong>exp:</strong> ${expiresAt}</p>
    </div>
    <div class="meta">
      <a class="button" href="/refresh-session">Refresh access token</a>
      <a class="button" href="/logout">Sign out</a>
    </div

