);

const cookieOptions = {
  httpOnly: true,
  sameSite: "lax"
};

const renderPage = (title, body) => `<!DOCTYPE html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <title>${title}</title>
    <style>
      body { font-family: Arial, sans-serif; margin: 40px; }
      .card { padding: 20px; border: 1px solid #ddd; border-radius: 8px; max-width: 640px; }
